-- pgcrypto lives in the Supabase `extensions` schema. SECURITY DEFINER functions use a restricted search_path,
-- so every digest call must be schema-qualified.

CREATE OR REPLACE FUNCTION public.create_sales_partner_agreement_internal(p_applicant_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_app public.applicants%ROWTYPE; v_tpl public.sales_agreement_templates%ROWTYPE; v_ctx jsonb; v_token uuid:=gen_random_uuid(); v_token_hash text; v_number text; v_id uuid; v_base text; v_url text; v_doc_hash text;
BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized.'; END IF; SELECT * INTO v_app FROM public.applicants WHERE id=p_applicant_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Candidate not found.'; END IF; IF COALESCE(trim(v_app.refusal_reason),'')<>'' THEN RAISE EXCEPTION 'A closed candidate cannot receive an agreement.'; END IF; IF v_app.stage NOT IN ('Selected','Agreement Pending') THEN RAISE EXCEPTION 'Candidate must be Selected or Agreement Pending before an agreement is issued.'; END IF; IF EXISTS(SELECT 1 FROM public.sales_partner_agreements WHERE applicant_id=p_applicant_id AND status IN ('Partner Signed','Verified')) THEN RAISE EXCEPTION 'A signed agreement already exists. Complete or formally supersede it before issuing another.'; END IF; SELECT * INTO v_tpl FROM public.sales_agreement_templates WHERE template_key='independent_sales_partner' AND status='Published' ORDER BY version DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'No published Sales Partner Agreement template exists.'; END IF; v_ctx:=public.build_sales_agreement_dynamic_snapshot(p_applicant_id); v_number:='PF-SPA-'||to_char(clock_timestamp(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); v_token_hash:=encode(extensions.digest(v_token::text,'sha256'),'hex'); v_doc_hash:=encode(extensions.digest((jsonb_build_object('agreementNumber',v_number,'templateVersion',v_tpl.version,'partner',v_ctx->'partner','company',v_ctx->'company','commercial',v_ctx->'commercial','training',v_ctx->'training','hiring',v_ctx->'hiring','template',jsonb_build_object('title',v_tpl.title,'subtitle',v_tpl.subtitle,'introduction',v_tpl.introduction,'sections',v_tpl.sections,'acknowledgements',v_tpl.acknowledgements)))::text,'sha256'),'hex'); UPDATE public.sales_partner_agreements SET status='Superseded',superseded_at=now(),updated_at=now() WHERE applicant_id=p_applicant_id AND status IN ('Sent','Viewed'); INSERT INTO public.sales_partner_agreements(agreement_number,applicant_id,template_id,template_version,status,token_hash,token_expires_at,partner_snapshot,company_snapshot,commercial_snapshot,training_snapshot,hiring_snapshot,template_snapshot,document_hash) VALUES(v_number,p_applicant_id,v_tpl.id,v_tpl.version,'Sent',v_token_hash,now()+interval '14 days',v_ctx->'partner',v_ctx->'company',v_ctx->'commercial',v_ctx->'training',v_ctx->'hiring',jsonb_build_object('title',v_tpl.title,'subtitle',v_tpl.subtitle,'introduction',v_tpl.introduction,'sections',v_tpl.sections,'acknowledgements',v_tpl.acknowledgements,'versionLabel',v_tpl.version_label),v_doc_hash) RETURNING id INTO v_id; INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_user_id,actor_email,metadata) VALUES(v_id,'Issued','Admin',auth.uid(),COALESCE((SELECT email FROM public.user_profiles WHERE id=auth.uid()),''),jsonb_build_object('templateVersion',v_tpl.version,'documentHash',v_doc_hash)); SELECT COALESCE(config_value->>'publicBaseUrl','https://www.profoxwebdesigner.com') INTO v_base FROM public.system_configuration WHERE config_key='notification_settings'; v_url:=rtrim(COALESCE(NULLIF(v_base,''),'https://www.profoxwebdesigner.com'),'/')||'/agreement/sign/'||v_token::text; PERFORM public.enqueue_notification('sales-agreement:'||v_id::text||':issued','recruitment_agreement_ready',v_app.email,NULL,public.recruitment_notification_payload(v_app)||jsonb_build_object('agreementUrl',v_url,'agreementNumber',v_number,'agreementId',v_id),now()); PERFORM set_config('profox.agreement_workflow_rpc','1',true); UPDATE public.applicants SET agreement_status='sent',updated_at=now() WHERE id=p_applicant_id; RETURN jsonb_build_object('agreementId',v_id,'agreementNumber',v_number,'signingUrl',v_url,'documentHash',v_doc_hash); END; $$;

CREATE OR REPLACE FUNCTION public.admin_resend_sales_partner_agreement(p_agreement_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row public.sales_partner_agreements%ROWTYPE; v_app public.applicants%ROWTYPE; v_token uuid:=gen_random_uuid(); v_url text; v_base text; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized.'; END IF; SELECT * INTO v_row FROM public.sales_partner_agreements WHERE id=p_agreement_id FOR UPDATE; IF NOT FOUND OR v_row.status NOT IN ('Sent','Viewed') THEN RAISE EXCEPTION 'Only an unsigned active agreement can be resent.'; END IF; SELECT * INTO v_app FROM public.applicants WHERE id=v_row.applicant_id; UPDATE public.sales_partner_agreements SET token_hash=encode(extensions.digest(v_token::text,'sha256'),'hex'),token_expires_at=now()+interval '14 days',status='Sent',sent_at=now(),updated_at=now() WHERE id=p_agreement_id; SELECT COALESCE(config_value->>'publicBaseUrl','https://www.profoxwebdesigner.com') INTO v_base FROM public.system_configuration WHERE config_key='notification_settings'; v_url:=rtrim(COALESCE(NULLIF(v_base,''),'https://www.profoxwebdesigner.com'),'/')||'/agreement/sign/'||v_token::text; PERFORM public.enqueue_notification('sales-agreement:'||p_agreement_id::text||':resent:'||extract(epoch from clock_timestamp())::bigint,'recruitment_agreement_ready',v_app.email,NULL,public.recruitment_notification_payload(v_app)||jsonb_build_object('agreementUrl',v_url,'agreementNumber',v_row.agreement_number,'agreementId',p_agreement_id),now()); INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_user_id,actor_email) VALUES(p_agreement_id,'Resent','Admin',auth.uid(),COALESCE((SELECT email FROM public.user_profiles WHERE id=auth.uid()),'')); RETURN jsonb_build_object('agreementId',p_agreement_id,'signingUrl',v_url); END; $$;

CREATE OR REPLACE FUNCTION public.public_get_sales_partner_agreement(p_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row public.sales_partner_agreements%ROWTYPE; BEGIN SELECT * INTO v_row FROM public.sales_partner_agreements WHERE token_hash=encode(extensions.digest(p_token::text,'sha256'),'hex') AND status IN ('Sent','Viewed','Partner Signed','Verified') AND (status IN ('Partner Signed','Verified') OR token_expires_at>now()) LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','This agreement link is invalid, expired or no longer active.'); END IF; IF v_row.status='Sent' THEN UPDATE public.sales_partner_agreements SET status='Viewed',viewed_at=COALESCE(viewed_at,now()),updated_at=now() WHERE id=v_row.id; INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_email) VALUES(v_row.id,'Viewed','Partner',COALESCE(v_row.partner_snapshot->>'email','')); v_row.status:='Viewed'; v_row.viewed_at:=now(); END IF; RETURN jsonb_build_object('success',true,'agreement',jsonb_build_object('id',v_row.id,'agreementNumber',v_row.agreement_number,'templateVersion',v_row.template_version,'status',v_row.status,'partner',v_row.partner_snapshot,'company',v_row.company_snapshot,'commercial',v_row.commercial_snapshot,'training',v_row.training_snapshot,'hiring',v_row.hiring_snapshot,'template',v_row.template_snapshot,'documentHash',v_row.document_hash,'sentAt',v_row.sent_at,'viewedAt',v_row.viewed_at,'partnerSignedAt',v_row.partner_signed_at,'companySignerName',v_row.company_signer_name,'companySignerTitle',v_row.company_signer_title,'companySignedAt',v_row.company_signed_at,'verifiedAt',v_row.verified_at,'executionHash',v_row.execution_hash)); END; $$;

CREATE OR REPLACE FUNCTION public.service_sign_sales_partner_agreement(p_token uuid,p_signer_name text,p_signature_svg text,p_acknowledgements jsonb,p_ip text DEFAULT '',p_user_agent text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_row public.sales_partner_agreements%ROWTYPE; v_app public.applicants%ROWTYPE; v_missing int; v_sig_hash text; v_admin record;
BEGIN SELECT * INTO v_row FROM public.sales_partner_agreements WHERE token_hash=encode(extensions.digest(p_token::text,'sha256'),'hex') AND status IN ('Sent','Viewed') AND token_expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Agreement link is invalid, expired, already signed or no longer active.'; END IF; IF lower(trim(COALESCE(p_signer_name,'')))<>lower(trim(COALESCE(v_row.partner_snapshot->>'fullName',''))) THEN RAISE EXCEPTION 'Typed legal name must match the name on the Agreement Record.'; END IF; IF COALESCE(length(p_signature_svg),0)<100 OR length(p_signature_svg)>120000 OR left(ltrim(p_signature_svg),4)<>'<svg' THEN RAISE EXCEPTION 'A valid drawn signature is required.'; END IF; SELECT count(*) INTO v_missing FROM jsonb_array_elements(v_row.template_snapshot->'acknowledgements') a WHERE COALESCE(p_acknowledgements->>(a->>'key'),'false')<>'true'; IF v_missing>0 THEN RAISE EXCEPTION 'All required acknowledgements must be accepted before signing.'; END IF; v_sig_hash:=encode(extensions.digest(p_signature_svg,'sha256'),'hex'); UPDATE public.sales_partner_agreements SET status='Partner Signed',partner_signer_name=trim(p_signer_name),partner_signature_svg=p_signature_svg,partner_signature_hash=v_sig_hash,partner_acknowledgements=p_acknowledgements,partner_signed_at=now(),partner_ip=left(COALESCE(p_ip,''),200),partner_user_agent=left(COALESCE(p_user_agent,''),1000),updated_at=now() WHERE id=v_row.id; INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_email,ip_address,user_agent,metadata) VALUES(v_row.id,'Partner Signed','Partner',COALESCE(v_row.partner_snapshot->>'email',''),left(COALESCE(p_ip,''),200),left(COALESCE(p_user_agent,''),1000),jsonb_build_object('signatureHash',v_sig_hash,'documentHash',v_row.document_hash)); SELECT * INTO v_app FROM public.applicants WHERE id=v_row.applicant_id; PERFORM public.enqueue_notification('sales-agreement:'||v_row.id::text||':partner-signed','recruitment_agreement_signature_received',v_app.email,NULL,public.recruitment_notification_payload(v_app)||jsonb_build_object('agreementNumber',v_row.agreement_number),now()); FOR v_admin IN SELECT id,email FROM public.user_profiles WHERE role='admin' AND status='active' LOOP PERFORM public.enqueue_in_app_notification(v_admin.id,'Recruitment','Agreement signature received',v_app.full_name||' signed the Sales Partner Agreement. Review and countersign it.','/admin/agreements','sales-agreement:partner-signed:'||v_row.id::text||':'||v_admin.id::text); END LOOP; SELECT id,email INTO v_admin FROM public.user_profiles WHERE role='admin' AND status='active' AND COALESCE(trim(email),'')<>'' ORDER BY CASE WHEN lower(trim(email))='mehtaba@profoxwebdesigner.com' THEN 0 ELSE 1 END,created_at LIMIT 1; IF v_admin.email IS NOT NULL THEN PERFORM public.enqueue_notification('sales-agreement:'||v_row.id::text||':admin-review','recruitment_admin_agreement_signed',lower(trim(v_admin.email)),v_admin.id,public.recruitment_notification_payload(v_app)||jsonb_build_object('agreementNumber',v_row.agreement_number,'agreementId',v_row.id),now()); END IF; RETURN jsonb_build_object('success',true,'agreementId',v_row.id,'agreementNumber',v_row.agreement_number,'status','Partner Signed'); END; $$;

CREATE OR REPLACE FUNCTION public.service_decline_sales_partner_agreement(p_token uuid,p_reason text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row public.sales_partner_agreements%ROWTYPE; BEGIN SELECT * INTO v_row FROM public.sales_partner_agreements WHERE token_hash=encode(extensions.digest(p_token::text,'sha256'),'hex') AND status IN ('Sent','Viewed') FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Agreement link is no longer active.'; END IF; UPDATE public.sales_partner_agreements SET status='Declined',declined_at=now(),updated_at=now() WHERE id=v_row.id; INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_email,metadata) VALUES(v_row.id,'Declined','Partner',COALESCE(v_row.partner_snapshot->>'email',''),jsonb_build_object('reason',left(COALESCE(p_reason,''),1000))); PERFORM set_config('profox.agreement_workflow_rpc','1',true); UPDATE public.applicants SET agreement_status='declined',refusal_reason=COALESCE(NULLIF(trim(p_reason),''),'Agreement Declined'),updated_at=now() WHERE id=v_row.applicant_id; RETURN jsonb_build_object('success',true,'status','Declined'); END; $$;

CREATE OR REPLACE FUNCTION public.admin_verify_sales_partner_agreement(p_agreement_id uuid,p_signer_name text,p_signer_title text,p_signature_svg text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row public.sales_partner_agreements%ROWTYPE; v_app public.applicants%ROWTYPE; v_sig_hash text; v_exec_hash text; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized.'; END IF; SELECT * INTO v_row FROM public.sales_partner_agreements WHERE id=p_agreement_id FOR UPDATE; IF NOT FOUND OR v_row.status<>'Partner Signed' THEN RAISE EXCEPTION 'Partner signature is required before company verification.'; END IF; IF COALESCE(trim(p_signer_name),'')='' OR COALESCE(trim(p_signer_title),'')='' THEN RAISE EXCEPTION 'Company signer name and title are required.'; END IF; IF COALESCE(length(p_signature_svg),0)<100 OR length(p_signature_svg)>120000 OR left(ltrim(p_signature_svg),4)<>'<svg' THEN RAISE EXCEPTION 'A valid company signature is required.'; END IF; v_sig_hash:=encode(extensions.digest(p_signature_svg,'sha256'),'hex'); v_exec_hash:=encode(extensions.digest(v_row.document_hash||'|'||COALESCE(v_row.partner_signature_hash,'')||'|'||v_sig_hash||'|'||v_row.partner_signed_at::text||'|'||now()::text,'sha256'),'hex'); UPDATE public.sales_partner_agreements SET status='Verified',company_signer_name=trim(p_signer_name),company_signer_title=trim(p_signer_title),company_signature_svg=p_signature_svg,company_signature_hash=v_sig_hash,company_signed_at=now(),company_signer_user_id=auth.uid(),verified_at=now(),verified_by=auth.uid(),execution_hash=v_exec_hash,updated_at=now() WHERE id=p_agreement_id; INSERT INTO public.sales_agreement_events(agreement_id,event_type,actor_type,actor_user_id,actor_email,metadata) VALUES(p_agreement_id,'Verified','Admin',auth.uid(),COALESCE((SELECT email FROM public.user_profiles WHERE id=auth.uid()),''),jsonb_build_object('companySignatureHash',v_sig_hash,'executionHash',v_exec_hash)); SELECT * INTO v_app FROM public.applicants WHERE id=v_row.applicant_id; PERFORM set_config('profox.agreement_workflow_rpc','1',true); UPDATE public.applicants SET agreement_status='signed',updated_at=now() WHERE id=v_row.applicant_id; PERFORM public.enqueue_notification('sales-agreement:'||p_agreement_id::text||':verified','recruitment_agreement_verified',v_app.email,NULL,public.recruitment_notification_payload(v_app)||jsonb_build_object('agreementNumber',v_row.agreement_number),now()); RETURN jsonb_build_object('success',true,'agreementId',p_agreement_id,'status','Verified','executionHash',v_exec_hash); END; $$;

REVOKE ALL ON FUNCTION public.create_sales_partner_agreement_internal(uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.service_sign_sales_partner_agreement(uuid,text,text,jsonb,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.service_decline_sales_partner_agreement(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.service_sign_sales_partner_agreement(uuid,text,text,jsonb,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.service_decline_sales_partner_agreement(uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.public_get_sales_partner_agreement(uuid) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_resend_sales_partner_agreement(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_verify_sales_partner_agreement(uuid,text,text,text) TO authenticated;
